FMT_EXPORT struct as_identifiers_t {};

/**
 * An annotation that makes an enum format as identifiers of its enumerators.
 *
 * **Example**:
 *
 *     enum class [[=fmt::as_identifiers]] color { red, green, blue };
 *     auto s = fmt::format("{}", color::green);  // s == "green"
 *
 * A value that doesn't match any enumerator is represented as its underlying
 * value in decimal before applying string formatting.
 */
FMT_EXPORT inline constexpr auto as_identifiers = as_identifiers_t();

static inline int fmt_vformat_cstr(char* buf, size_t size, int result) {
  if (result >= 0 && (size_t)result < size)
    buf[result] = '\0';
  else if (size > 0)
    buf[size - 1] = '\0';
  return result;
}

#define fmt_format_cstr(buf, size, ...) \
  fmt_vformat_cstr(buf, size, fmt_format(buf, size, __VA_ARGS__))

static inline fmt_arg fmt_from_uint(unsigned long long x) {
  return (fmt_arg){.type = fmt_uint, .value.uint_value = x};
}

struct color_type {
  constexpr color_type() noexcept = default;
  constexpr color_type(color rgb_color) noexcept
      : value_(static_cast<uint32_t>(rgb_color) | (1 << 24)) {}
  constexpr color_type(rgb rgb_color) noexcept
      : color_type(static_cast<color>(
            (static_cast<uint32_t>(rgb_color.r) << 16) |
            (static_cast<uint32_t>(rgb_color.g) << 8) | rgb_color.b)) {}
  constexpr color_type(terminal_color term_color) noexcept
      : value_(static_cast<uint32_t>(term_color) | (3 << 24)) {}

  constexpr auto is_terminal_color() const noexcept -> bool {
    return (value_ & (1 << 25)) != 0;
  }

  constexpr auto value() const noexcept -> uint32_t {
    return value_ & 0xFFFFFF;
  }

  constexpr color_type(uint32_t value) noexcept : value_(value) {}

  uint32_t value_ = 0;
};
}  // namespace detail

/// A text style consisting of foreground and background colors and emphasis.

 * **Example**:
 *
 *     enum class [[=fmt::as_identifiers]] color { red, green, blue };
 *     auto s = fmt::format("{}", color::green);  // s == "green"
 *
 * A value that doesn't match any enumerator is represented as its underlying
 * value in decimal before applying string formatting.
 */
FMT_EXPORT inline constexpr auto as_identifiers = as_identifiers_t();

FMT_EXPORT struct as_underlying_t {};

/**
 * An annotation that makes an enum format as its underlying value.
 *
 * **Example**:
 *
 *     enum class [[=fmt::as_underlying]] color { red = 1, green = 2 };
 *     auto s = fmt::format("{:04x}", color::green);  // s == "0002"
 */
FMT_EXPORT inline constexpr auto as_underlying = as_underlying_t();

namespace detail {

// Returns true if U is annotated with an annotation of type A.
template <typename A, typename U> consteval auto is_annotated() -> bool {
  return !std::meta::annotations_of_with_type(^^U, ^^A).empty();
}

// Returns true if T is an enum annotated with fmt::as_identifiers.
template <typename T, typename U = remove_cvref_t<T>>
consteval auto use_identifiers() -> bool {
  if constexpr (std::is_enum<U>::value) {
    return is_annotated<as_identifiers_t, U>();
  } else {
    return false;
  }
}

// Returns true if T is an enum annotated with fmt::as_underlying.
template <typename T, typename U = remove_cvref_t<T>>
consteval auto use_underlying() -> bool {
  if constexpr (std::is_enum<U>::value) {
    // The annotations specify different representations. Reporting this here
    // gives a better diagnostic than an ambiguous formatter specialization.
    static_assert(!is_annotated<as_underlying_t, U>() ||
                      !is_annotated<as_identifiers_t, U>(),
                  "fmt::as_underlying and fmt::as_identifiers are mutually "
                  "exclusive");
    return is_annotated<as_underlying_t, U>();

  return static_cast<uint64_t>(background.value_) << 27;
}

FMT_CONSTEXPR inline auto operator|(emphasis lhs, emphasis rhs) noexcept
    -> text_style {
  return text_style(lhs) | rhs;
}

namespace detail {

template <typename Char> struct ansi_color_escape {
  FMT_CONSTEXPR ansi_color_escape(color_type text_color,
                                  const char* esc) noexcept {
    // If we have a terminal color, we need to output another escape code
    // sequence.
    if (text_color.is_terminal_color()) {
      bool is_background = esc == string_view("\x1b[48;2;");
      uint32_t value = text_color.value();
      // Background ASCII codes are the same as the foreground ones but with
      // 10 more.
      if (is_background) value += 10u;

      buffer[size++] = static_cast<Char>('\x1b');
      buffer[size++] = static_cast<Char>('[');

      if (value >= 100u) {
        buffer[size++] = static_cast<Char>('1');
        value %= 100u;
      }
      buffer[size++] = static_cast<Char>('0' + value / 10u);
      buffer[size++] = static_cast<Char>('0' + value % 10u);

      buffer[size++] = static_cast<Char>('m');
      return;
    }

    for (int i = 0; i < 7; i++) {
      buffer[i] = static_cast<Char>(esc[i]);
    }
    rgb color(text_color.value());
    to_esc(color.r, buffer + 7, ';');
    to_esc(color.g, buffer + 11, ';');
    to_esc(color.b, buffer + 15, 'm');
    size = 19;
  }
  FMT_CONSTEXPR ansi_color_escape(emphasis em) noexcept {
    uint8_t em_codes[num_emphases] = {};
    if (has_emphasis(em, emphasis::bold)) em_codes[0] = 1;
    if (has_emphasis(em, emphasis::faint)) em_codes[1] = 2;
    if (has_emphasis(em, emphasis::italic)) em_codes[2] = 3;

